set-variable.value:
@{
          var token = context.Request.Url.Query.GetValueOrDefault("gateway-token", "");
          if (token.Length > 4096) { return ""; }
          token = Uri.UnescapeDataString(token);
          var parts = token.Split('.');
          if (parts.Length != 2) { return ""; }
          var expected = Convert.ToBase64String(new System.Security.Cryptography.HMACSHA256(Encoding.UTF8.GetBytes("{{polling-signing-key}}")).ComputeHash(Encoding.UTF8.GetBytes(parts[0])));
          if (expected.Length != parts[1].Length) { return ""; }
          var difference = 0;
          for (var i = 0; i < expected.Length; i++) { difference |= expected[i] ^ parts[1][i]; }
          if (difference != 0) { return ""; }
          return Encoding.UTF8.GetString(Convert.FromBase64String(parts[0]));
        }

@{
          var text = (string)context.Variables["tokenPayload"];
          if (String.IsNullOrEmpty(text)) { return false; }
          var payload = Newtonsoft.Json.Linq.JObject.Parse(text);
          var now = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
          return (string)payload["operation"] == context.Request.MatchedParameters["operationId"]
            && (new [] { "{{cu-region}}", "{{cu-secondary-region}}" }).Contains((string)payload["region"])
            && (string)payload["gateway"] == "{{gateway-name}}"
            && (string)payload["subscription"] == context.Subscription.Id
            && (string)payload["apiVersion"] == context.Request.Url.Query.GetValueOrDefault("api-version", "")
            && (long)payload["started"] <= now
            && now <= (long)payload["started"] + {{token-lifetime}}L * 1000
            && context.Request.OriginalUrl.Host.Equals(new Uri("{{gateway-url}}").Host, StringComparison.OrdinalIgnoreCase);
        }

@{
      if (context.Request.Method == "POST") {
        return context.Response.StatusCode == 429 || context.Response.StatusCode >= 500 ? "backend-error" : "";
      }
      if (context.Response.StatusCode != 200) { return ""; }
      var body = context.Response.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
      var status = ((string)body["status"] ?? "").ToLowerInvariant();
      if ((double)context.Variables["elapsedSeconds"] <= {{latency-threshold}}) { return ""; }
      return status == "succeeded" ? "completion-latency"
        : status == "running" || status == "notstarted" ? "pending-latency" : "";
    }

@{
          var value = context.Response.Headers.GetValueOrDefault("Operation-Location", "");
          Uri url;
          if (!value.StartsWith("https://", StringComparison.OrdinalIgnoreCase)
            || !Uri.TryCreate(new Uri((string)context.Variables["cuEndpoint"]), value, out url)) { return false; }
          return url.Scheme == "https" && url.Authority.Equals(new Uri((string)context.Variables["cuEndpoint"]).Authority, StringComparison.OrdinalIgnoreCase)
            && String.IsNullOrEmpty(url.UserInfo) && String.IsNullOrEmpty(url.Fragment)
            && Regex.IsMatch(url.AbsolutePath, "^/contentunderstanding/analyzerResults/[a-zA-Z0-9_-]+$")
            && ("&" + url.Query.TrimStart('?') + "&").Contains("&api-version={{cu-api-version}}&")
            && !Regex.IsMatch(url.Query, "[?&]gateway-token=")
            && !String.IsNullOrEmpty(context.Request.Url.Query.GetValueOrDefault("api-version", ""));
        }

set-header.value:
@{
          var url = new Uri(context.Response.Headers.GetValueOrDefault("Operation-Location", ""));
          var operation = url.AbsolutePath.Substring(url.AbsolutePath.LastIndexOf('/') + 1);
          var payload = new Newtonsoft.Json.Linq.JObject(
            new Newtonsoft.Json.Linq.JProperty("operation", operation),
            new Newtonsoft.Json.Linq.JProperty("region", (string)context.Variables["cuRegion"]),
            new Newtonsoft.Json.Linq.JProperty("gateway", "{{gateway-name}}"),
            new Newtonsoft.Json.Linq.JProperty("subscription", context.Subscription.Id),
            new Newtonsoft.Json.Linq.JProperty("apiVersion", context.Request.Url.Query.GetValueOrDefault("api-version", "")),
            new Newtonsoft.Json.Linq.JProperty("analyzer", context.Request.MatchedParameters["analyzerId"]),
            new Newtonsoft.Json.Linq.JProperty("started", new DateTimeOffset(context.Timestamp).ToUnixTimeMilliseconds())
          ).ToString(Newtonsoft.Json.Formatting.None);
          var encoded = Convert.ToBase64String(Encoding.UTF8.GetBytes(payload));
          var signature = Convert.ToBase64String(new System.Security.Cryptography.HMACSHA256(Encoding.UTF8.GetBytes("{{polling-signing-key}}")).ComputeHash(Encoding.UTF8.GetBytes(encoded)));
          var apiPath = context.Api.Path.Trim('/');
          return "{{gateway-url}}" + (String.IsNullOrEmpty(apiPath) ? "" : "/" + apiPath) + "/analyzerResults/" + operation
            + (String.IsNullOrEmpty(url.Query) ? "?api-version=" + Uri.EscapeDataString(context.Request.Url.Query.GetValueOrDefault("api-version", "")) : url.Query)
            + "&gateway-token=" + Uri.EscapeDataString(encoded + "." + signature);
        }

set-variable.value:
@{
          var body = context.Response.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
          var status = ((string)body["status"] ?? "").ToLowerInvariant();
          return new [] { "notstarted", "running", "succeeded", "failed", "canceled" }.Contains(status) ? status : "invalid";
        }
